// Compact fighter creation flow aligned with the inspected mobile form.
const fighterTypesByFaction={
'House Escher':['Queen','Matriarch','Death-maiden','Sister','Little Sister','Wyld Runner'],
'House Goliath':['Forge Tyrant','Forge Boss','Stimmer','Bruiser','Bully','Forgeborn'],
'House Orlock':['Road Captain','Road Sergeant','Arms Master','Gunner','Wrecker','Greenhorn'],
'House Van Saar':['Prime','Augmek','Archeotek','Tek','Subtek','Neotek'],
'House Cawdor':['Word-Keeper','Firebrand','Deacon','Brethren','Bonepicker'],
'House Delaque':['Master of Shadow','Phantom','Nacht-Ghul','Ghost','Shadow','Psy-Gheist'],
'Corpse Grinder Cults':['Butcher','Cutter','Skinner','Initiate']};
const previousEditFighterUI=editFighter;
editFighter=function(f){if(f)return previousEditFighterUI(f);ensureAssets();let g=gang(),common=fighterTypesByFaction[g.faction]||['Leader','Champion','Ganger','Juve','Prospect','Brute'];let fields=`<label>Fighter Type *<select name="preset" required><option value="">Select fighter type</option>${common.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}<option value="__custom">Custom Fighter Type</option></select></label><label class="checkline"><input type="checkbox" name="includeCustom" value="yes"> Include Custom Fighter Types <span title="Show fighter types you created in Custom Assets">ⓘ</span></label><label class="checkline"><input type="checkbox" name="includeAll" value="yes"> Include all Fighter Types <span title="Show types from every gang">ⓘ</span></label><label id="custom-type-wrap" hidden>Custom Fighter Type<input name="customType" type="text" placeholder="Enter fighter type"></label><label>Cost (credits) *<input name="cost" type="number" min="0" required placeholder="Enter fighter cost"></label><label class="checkline"><input type="checkbox" name="listedCost" value="yes" checked> Use Listed Cost for Rating <span title="Include this cost in gang rating">ⓘ</span></label><label>Fighter Name *<input name="name" type="text" required placeholder="Enter fighter name"></label>`;
formModal('Add Fighter',fields,v=>{let type=v.preset==='__custom'?v.customType.trim():v.preset;if(!type){alert('Fighter Type is required.');return false}if(n(v.cost)>n(g.credits)){alert('Not enough credits to add this fighter.');return false}let fighter={id:id(),name:v.name.trim(),type,cost:n(v.cost),ratingCost:n(v.cost),status:'Active',xp:0,kills:0,stats:{...baseStats},equipment:[],skills:[],effects:[],notes:'',listedCost:v.listedCost==='yes'};g.fighters.push(fighter);g.credits-=fighter.cost;log(g,`${fighter.name} 파이터를 추가했습니다.`);save()},'Add Fighter');
$('.modal').classList.add('fighter-create');$('#modal-cancel').textContent='Cancel';$('.modal-head .icon-btn').insertAdjacentHTML('beforebegin',`<div class="modal-header-right"><span>Gang Credits</span><span class="credit-pill">${fmt(g.credits)}</span></div>`);
let form=$('#modal-form'),selector=form.querySelector('[name="preset"]'),custom=form.querySelector('[name="includeCustom"]'),all=form.querySelector('[name="includeAll"]');function options(){let current=selector.value,types=[...common];if(all.checked)types=[...new Set([...Object.values(fighterTypesByFaction).flat(),...types,'Leader','Champion','Ganger','Juve','Prospect','Brute'])];if(custom.checked)types=[...new Set([...types,...data.customAssets.fighters.map(x=>x.name)])];selector.innerHTML='<option value="">Select fighter type</option>'+types.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')+'<option value="__custom">Custom Fighter Type</option>';selector.value=types.includes(current)||current==='__custom'?current:''}custom.onchange=all.onchange=options;selector.onchange=()=>{let chosen=selector.value,asset=data.customAssets.fighters.find(x=>x.name===chosen);form.querySelector('#custom-type-wrap').hidden=chosen!=='__custom';if(asset)form.querySelector('[name="cost"]').value=asset.cost||0};
};
